from lib import *
S = SS('x13')
steps = [
    step("同步事件。publishEvent(OrderPlaced A1, 金额 50):监听器全部在发布者所在的 main 线程里执行,顺序是 first(@Order(1))、second(@Order(2)),然后 chain 监听器的返回值(一个 Evt)被自动发布,onEvt 收到它,最后 publishEvent 才返回。金额 500 的 A2 多了 big(condition amount>100)。发布者一直在等,监听器没处理完它不会返回。泛型事件:普通的 Box<String> 和 Box<Integer> 事件发布后,没有任何 Box 监听器被调用;让事件类实现 ResolvableTypeProvider 之后,BoxR<String> 只被 String 的监听器收到(同时也被它的父类型监听器 Box<String> 收到),BoxR<Integer> 同理。", t=tl(S(1)), mark=lidx(S(1), '没有任何 Box 监听器被调用的记录', 'BoxR<String> 的监听器收到', 'BoxR<Integer> 的监听器收到'), done=lidx(S(1), 'first(@Order(1)) 收到 A1', 'second(@Order(2)) 收到 A1', 'onEvt 收到 由监听器的返回值发布:A1', 'big(condition amount>100)'), b=bars([['A1 触发的监听器调用', 3, '3(first、second、onEvt)'], ['A2 触发的监听器调用', 4, '4(多了 big)'], ['普通 Box 事件触发的监听器', 0, '0'], ['BoxR 事件触发的监听器', 4, '4']], 4, done=[0, 1], mark=[2], cur=[3]), kv=KV([['执行线程', '发布者的 main 线程'], ['发布者', '等所有监听器处理完'], ['condition', 'SpEL 过滤,amount>100 才进 big'], ['泛型事件', '要实现 ResolvableTypeProvider 才按泛型匹配']], ['泛型事件'])),
    step("同步监听器抛异常。bad(@Order(1))先执行并抛出 IllegalStateException:监听器失败;after(@Order(2))没有被执行;异常直接抛给了 publishEvent 的调用者。同步事件里一个监听器失败,后面的监听器全部跳过,发布者也跟着失败。", t=tl(S(2)), mark=lidx(S(2), 'publishEvent 抛给了发布者'), done=lidx(S(2), 'bad(@Order(1)) 抛异常'), b=bars([['bad 执行', 1, '1'], ['after 执行', 0, '0(被跳过)'], ['异常到达发布者', 1, '是']], 1, done=[0], mark=[1, 2]), kv=KV([['bad(@Order(1))', '抛异常'], ['after(@Order(2))', '没有执行'], ['发布者', '收到 IllegalStateException'], ['含义', '同步事件里监听器失败会波及发布者']], ['含义'])),
    step("多播器配线程池(SimpleApplicationEventMulticaster.setTaskExecutor)加 ErrorHandler。第一个 publishEvent 返回只用了 0 ms,第二个也立刻返回;监听器在 event-pool 线程里执行:bad 抛异常,ErrorHandler 收到“监听器失败”,after 照样执行(异常没有挡住它),Slow 监听器睡 300 ms 后处理完 B1。发布者不等,异常也不会传回发布者。", t=tl(S(3)), mark=lidx(S(3), 'ErrorHandler 收到异常', 'Slow 监听器处理完 B1'), done=lidx(S(3), 'publishEvent 返回,用了', '第二个 publishEvent 返回', 'after(@Order(2)) 收到'), b=bars([['发布者等待的时间 ms', 0, '0'], ['Slow 监听器睡的时间 ms', 300, '300'], ['after 在 bad 抛异常后执行', 1, '执行了']], 300, done=[0, 2], cur=[1]), kv=KV([['线程', 'event-pool,不是发布者'], ['发布者', '立刻返回'], ['异常', '交给 ErrorHandler,不传回发布者'], ['after', '不受 bad 异常影响']], ['异常'])),
    step("在 bean 初始化阶段发布事件。Early 的 @PostConstruct 里发布 Evt(此时容器还在 refresh 的单例创建阶段):实现了 ApplicationListener 的 Bean(Cls)收到了;用 @EventListener 方法的 Anno 没有收到。@EventListener 方法要等 EventListenerMethodProcessor 在所有单例创建完之后才注册成监听器,在这之前发布的事件它错过了。", t=tl(S(4)), mark=lidx(S(4), 'Early.@PostConstruct 发布完毕'), done=lidx(S(4), 'ApplicationListener 类型的 Bean 收到'), b=bars([['ApplicationListener 类型的 Bean 收到', 1, '收到'], ['@EventListener 方法收到', 0, '没收到']], 1, done=[0], mark=[1]), kv=KV([['事件发布时机', '单例创建阶段(Early.@PostConstruct)'], ['ApplicationListener Bean', '已按名字登记,收到'], ['@EventListener 方法', '尚未注册,错过'], ['建议', '启动阶段的通知用 ContextRefreshedEvent 之后']], ['@EventListener 方法'])),
    step("容器自带的事件顺序(refresh、start、stop、close 各调用一次):ContextRefreshedEvent、ContextStartedEvent、ContextStoppedEvent、ContextClosedEvent,都在 main 线程。refresh 完成发的是 Refreshed,start() 才发 Started,和 Boot 的 ApplicationReadyEvent 不是一回事(见后面的 Boot 篇)。", t=tl(S(5)), mark=lidx(S(5), 'ContextRefreshedEvent'), done=lidx(S(5), 'ContextStartedEvent', 'ContextStoppedEvent', 'ContextClosedEvent'), b=bars([['内置事件数', 4, '4']], 4, done=[0]), kv=KV([['refresh()', 'ContextRefreshedEvent'], ['start()', 'ContextStartedEvent'], ['stop()', 'ContextStoppedEvent'], ['close()', 'ContextClosedEvent']], ['start()'])),
]
A = mkartx('x13', 13, 'Spring,事件,ApplicationEvent,EventListener,异步事件,真实验证,动画演示',
    '实测 Spring 事件机制:默认同步,监听器在发布者线程里依次执行,一个失败后面的跳过且异常传回发布者;多播器配线程池后发布者 0 ms 返回、异常交给 ErrorHandler;泛型事件要实现 ResolvableTypeProvider 才按泛型匹配;在 @PostConstruct 里发布的事件会被 @EventListener 方法错过,ApplicationListener 的 Bean 却能收到。',
    '事件发布到底是同步还是异步?监听器抛异常会怎样?泛型事件怎么匹配?启动过程中发布的事件为什么有的监听器收不到?这篇在 Spring Framework 7.0.9 上逐项验证。',
    [('0 ms', '多播器配了线程池后 publishEvent 返回花的时间(监听器在 event-pool 线程里执行)'), ('0 个', '同步监听器 bad 抛异常后,排在它后面的 after 监听器被执行的个数(异常直接抛给了发布者)'), ('错过', '在 Bean 的 @PostConstruct 里发布的事件,@EventListener 方法没有收到,ApplicationListener 的 Bean 收到了')],
    [('同步', '<p>监听器在发布者线程里依次执行,@Order 排序,返回值被当作新事件发布,condition 用 SpEL 过滤。</p>'),
     ('异常', '<p>同步事件里监听器抛异常,后面的监听器跳过,异常抛给发布者。</p>'),
     ('异步', '<p>给多播器配线程池后发布者立刻返回,异常交给 ErrorHandler。</p>'),
     ('启动阶段', '<p>@EventListener 方法在单例创建完之后才注册,更早发布的事件它收不到。</p>'),
     ('内置事件', '<p>refresh、start、stop、close 各发一个对应的 Context 事件。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9;异步通过给 SimpleApplicationEventMulticaster 设置 TaskExecutor 实现,没有测 @Async 加 @EventListener 的写法;“@EventListener 方法在所有单例创建完之后才注册”是根据现象(Anno 没收到,Cls 收到了)的解释,没有读 EventListenerMethodProcessor 的源码',
     '没有验证:@Async 与 @EventListener 组合;@TransactionalEventListener(见事务篇);事件监听器的执行耗时对发布者的影响;ApplicationEventMulticaster 的缓存机制;Boot 的 ApplicationStartedEvent / ApplicationReadyEvent(见后面的 Boot 篇)'],
    'Spring 的事件机制')
